create or replace function public.j17_ready(a jsonb, recipe jsonb) returns boolean
language sql immutable set search_path='' as $$
 select coalesce(jsonb_array_length(recipe->'needs')>0,false) and not exists(select 1 from jsonb_array_elements(recipe->'needs') t(x)
 where public.jiuli_secure_int(a->(x->>0),x->>1)<(x->>2)::int)
$$;
create or replace function public.j17_cook(a jsonb, dish text, recipe jsonb, at_ms bigint)
returns jsonb language plpgsql set search_path='' as $$
declare x jsonb;
begin
 if jsonb_array_length(a->'kitchen')>=4+greatest(1,public.jiuli_secure_int(a,'restaurantLevel')) then raise exception '廚房已滿';end if;
 if not public.j17_ready(a,recipe) then raise exception '料理材料不足';end if;
 for x in select value from jsonb_array_elements(recipe->'needs') loop
  a:=public.jiuli_secure_adjust(a,x->>0,x->>1,-(x->>2)::int);
 end loop;
 a:=jsonb_set(a,'{kitchen}',(a->'kitchen')||jsonb_build_array(jsonb_build_object('name',dish,'price',(recipe->>'sell')::bigint,'readyAt',at_ms+greatest(15000,(recipe->>'minutes')::int*3000))));
 a:=public.jiuli_secure_adjust(a,'stats','cooked',1);
 return public.jiuli_secure_set(a,'xp',public.jiuli_secure_int(a,'xp')+12);
end $$;
create or replace function public.j17_collect(a jsonb,t bigint) returns jsonb language sql immutable set search_path='' as $$
 select a||jsonb_build_object('kitchen',coalesce(jsonb_agg(x order by i) filter(where (x->>'readyAt')::bigint>t),'[]'),
 'dishes',coalesce(a->'dishes','[]')||coalesce(jsonb_agg(jsonb_build_object('name',x->>'name','price',x->'price','finishedAt',x->'readyAt') order by i) filter(where (x->>'readyAt')::bigint<=t),'[]'))
 from jsonb_array_elements(a->'kitchen') with ordinality as jobs(x,i)
$$;
create or replace function public.j17_service(a jsonb,t bigint) returns jsonb language plpgsql set search_path='' as $$
declare r record; exp bigint:=public.jiuli_secure_int(a,'cookUntil'); collected int; before_count int;
begin
 if exp=0 then return a;end if;
 before_count:=jsonb_array_length(a->'kitchen');
 a:=public.j17_collect(a,least(t,exp));
 collected:=before_count-jsonb_array_length(a->'kitchen');
 if collected>0 then a:=public.jiuli_secure_set(a,'autoCollected',public.jiuli_secure_int(a,'autoCollected')+collected); end if;
 if exp<=t then return a;end if;
 for k in 1..(4+greatest(1,public.jiuli_secure_int(a,'restaurantLevel'))-jsonb_array_length(a->'kitchen')) loop
  select name,attrs into r from public.jiuli_secure_catalog where kind='recipe' and public.j17_ready(a,attrs) order by (attrs->>'sell')::int desc,name limit 1;
  if not found then exit;end if;
  a:=public.j17_cook(a,r.name,r.attrs,t);
 end loop;
 return a;
end $$;
create or replace function public.j17_kitchen_clock() returns void language plpgsql security definer set search_path='' as $$
declare t bigint:=(extract(epoch from clock_timestamp())*1000)::bigint; acct record; updated jsonb;
begin
 perform pg_advisory_xact_lock(2026,1118);
 for acct in select user_id,state from public.jiuli_secure_accounts
 where public.jiuli_secure_int(state,'cookUntil')>0 and exists(select 1 from jsonb_array_elements(state->'kitchen') k where (k->>'readyAt')::bigint<=least(t,public.jiuli_secure_int(state,'cookUntil'))) for update loop
  updated:=public.j17_service(acct.state,t);
  if updated<>acct.state then update public.jiuli_secure_accounts set state=updated,revision=revision+1,updated_at=now() where user_id=acct.user_id;end if;
 end loop;
end $$;
create or replace function public.j17_ranking(scope text,metric text,page_no int default 0)
returns jsonb language sql stable security definer set search_path='' as $$
 with scores as (
 select a.user_id,coalesce(nullif(p.display_name,''),a.state->>'name','靈貓旅人') as player,
 case when metric='fish' then jsonb_array_length(a.state->'discovered') else public.jiuli_secure_int(a.state,metric) end score
 from public.jiuli_secure_accounts a left join public.jiuli_web_profiles p on p.user_id=a.user_id
 where auth.uid() is not null and metric in ('gold','yuanbao','fish','deliveries','restaurantSales','charisma','generosity') and (scope='world' or (scope='friends' and (a.user_id=auth.uid() or exists(
 select 1 from public.jiuli_social_friends f where f.status='accepted' and f.user_a=least(a.user_id,auth.uid()) and f.user_b=greatest(a.user_id,auth.uid())))))),
 ranked as(select *,rank() over(order by score desc) position from scores),
 page as(select position,player,score,user_id=auth.uid() mine from ranked order by position,user_id limit 25 offset greatest(page_no,0)::bigint*25)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'),'count',(select count(*) from ranked),'me',(select position from ranked where user_id=auth.uid()))
$$;
revoke all on function public.j17_kitchen_clock(),public.j17_service(jsonb,bigint),public.j17_cook(jsonb,text,jsonb,bigint),public.j17_collect(jsonb,bigint),public.j17_ready(jsonb,jsonb),public.j17_ranking(text,text,int) from public,anon,authenticated;
grant execute on function public.j17_ranking(text,text,int) to authenticated;

