create extension if not exists pg_cron;
select cron.schedule('jiuli-kitchen-v17','* * * * *','select public.j17_kitchen_clock()');
do $$ begin if (select count(*) from public.jiuli_secure_catalog where kind='recipe' and attrs ? 'needs')<>500 then raise exception '食譜目錄不完整';end if;end $$;
-- Run against the actual catalog using a temporary JSON value only.
do $verify$
declare
 t bigint:=1800000000000;
 a jsonb:=jsonb_build_object('kitchen','[]'::jsonb,'dishes','[]'::jsonb,'crops','{"番茄":2}'::jsonb,'items','{"雞蛋":2,"食用油":1,"鹽巴":1}'::jsonb,'cookUntil',1800000600000);
 expected text; cooked jsonb; collected jsonb; due bigint;
begin
 select name into expected from public.jiuli_secure_catalog where kind='recipe' and public.j17_ready(a,attrs) order by (attrs->>'sell')::int desc,name limit 1;
 if expected is distinct from '番茄炒蛋' then raise exception '預期番茄炒蛋，資料目錄與配方不符';end if;
 cooked:=public.j17_service(a,t);
 if jsonb_array_length(cooked->'kitchen')<>1 or cooked#>>'{kitchen,0,name}'<>expected or public.jiuli_secure_int(cooked->'items','雞蛋')<>0 then raise exception '扣料或自動選菜錯誤';end if;
 due:=(cooked#>>'{kitchen,0,readyAt}')::bigint;
 if public.j17_collect(cooked,due-1)<>cooked then raise exception '尚未完成的料理被提早收取';end if;
 collected:=public.j17_service(cooked,due);
 if jsonb_array_length(collected->'kitchen')<>0 or jsonb_array_length(collected->'dishes')<>1 or public.j17_service(collected,due)<>collected then raise exception '收餐或重試驗證失敗';end if;
 a:=jsonb_set(a,'{crops}','{"番茄":2,"晨露藍莓":3,"草莓":3}'::jsonb);
 a:=jsonb_set(a,'{items}',(a->'items')||'{"砂糖":8,"檸檬汁":8}'::jsonb);
 select name into expected from public.jiuli_secure_catalog where kind='recipe' and public.j17_ready(a,attrs) order by (attrs->>'sell')::int desc,name limit 1;
 cooked:=public.j17_service(a,t);
 if (cooked#>>'{kitchen,0,name}') is distinct from expected or jsonb_array_length(cooked->'kitchen')<2 then raise exception '最高價值優先或多鍋驗證失敗';end if;
 if public.j17_service(a,1800000600001)->'kitchen'<>'[]'::jsonb then raise exception '會員到期後仍在開鍋';end if;
end $verify$;
